package com.ruoyi.medical.persistence;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.*;import org.springframework.transaction.support.TransactionSynchronizationManager;import com.ruoyi.medical.persistence.mapper.SourceReadMapper;
/** Actual EvaluationService private definition and actual Admission private proof; external policy/budget/SQL doubles. */
class ExecutionAdmissionSnapshotTest {
 final ExecutionDefinitionSnapshotTest original=new ExecutionDefinitionSnapshotTest();final FormalAgentCandidateAuthority candidates=mock(FormalAgentCandidateAuthority.class);final FormalAgentCandidateAuthority.VerifiedCandidateIdentity candidate=mock(FormalAgentCandidateAuthority.VerifiedCandidateIdentity.class);final AgentExecutionPolicyAuthority policies=mock(AgentExecutionPolicyAuthority.class);final AgentExecutionPolicyAuthority.VerifiedPolicy policy=mock(AgentExecutionPolicyAuthority.VerifiedPolicy.class);final AgentExecutionPolicyProtocol.Definition definition=mock(AgentExecutionPolicyProtocol.Definition.class);final RunCreateBudget budgets=mock(RunCreateBudget.class);final JdbcTemplate db=mock(JdbcTemplate.class);final FormalEvaluationExecutionAdmission service;final FormalEvaluationExecutionProtocol.Start start;
 ExecutionAdmissionSnapshotTest()throws Exception{
  var d=original.definition;start=new FormalEvaluationExecutionProtocol.Start("1.0.0",d.evaluation_id(),original.schema.hash(d),"1",d.request().candidates().get(0),EvaluationFixture.ref(60),EvaluationFixture.ref(70),EvaluationFixture.ref(71));when(original.actor.context().context_revision()).thenReturn("1");
  when(candidates.require(any(),any(),any(),any())).thenReturn(candidate);when(candidate.executionPolicy()).thenReturn(start.executionPolicy());when(candidate.status()).thenReturn("DRAFT");when(candidate.classification()).thenReturn("INTERNAL");when(candidate.runtimeManifestSha256()).thenReturn("a".repeat(64));when(candidate.authorizations()).thenReturn(original.json.object());
  when(policies.requireByVersion(any(),any(),any(),any(),any(),any())).thenReturn(policy);when(policy.definition()).thenReturn(definition);when(policy.businessPurpose()).thenReturn("DOCUMENT_BODY");when(policy.authorizations()).thenReturn(original.json.object());when(definition.environment()).thenReturn("PRODUCTION");when(definition.bindings()).thenReturn(List.of(new AgentExecutionPolicyProtocol.NodeBinding("N00",EvaluationFixture.ref(75),null,null,null,original.json.object(),List.of())));when(definition.sourceSelection()).thenReturn(new AgentExecutionPolicyProtocol.SourceSelection(EvaluationFixture.ref(76),"FIXED_SOURCE_VERSIONS",List.of()));
  when(db.query(anyString(),any(RowMapper.class))).thenReturn(List.of(java.time.LocalDateTime.of(2026,10,18,0,0)));when(db.query(anyString(),any(RowMapper.class),any(Object[].class))).thenReturn(List.of("USD"));
  when(budgets.require(any(),anyMap(),any(),anyString())).thenAnswer(i->{Map<String,Object> v=i.getArgument(1);var n=original.json.object().put("content_sha256","a".repeat(64)).put("budget_id",v.get("budgetRevision").toString());if(v.get("budgetRevision").equals(start.enterpriseBudget().version_id()))n.putNull("project_id");else n.put("project_id",d.request().project_id());return n;});
  service=new FormalEvaluationExecutionAdmission(original.service,candidates,policies,mock(EvaluationReferences.class),mock(SourceReadAuthority.class),mock(SourceReadMapper.class),budgets,original.json,db);
 }
 FormalEvaluationExecutionAdmission.Prepared read()throws Exception{return service.require(original.actor,"1",start);}
 @Test void truePrivateAdmissionDoesNotExposeMutableDefinition()throws Exception{try(var scope=original.scope()){TransactionSynchronizationManager.setActualTransactionActive(true);try{var proof=read();((com.fasterxml.jackson.databind.node.ObjectNode)proof.definition().candidate_snapshots().get(0).limits()).put("forged",true);assertFalse(proof.definition().candidate_snapshots().get(0).limits().has("forged"));proof.requireUnchanged();}finally{TransactionSynchronizationManager.clear();}}}
 @Test void truePrivateAdmissionRejectsNewSameIdentityScope()throws Exception{FormalEvaluationExecutionAdmission.Prepared proof;try(var scope=original.scope()){TransactionSynchronizationManager.setActualTransactionActive(true);try{proof=read();}finally{TransactionSynchronizationManager.clear();}}try(var scope=original.scope()){TransactionSynchronizationManager.setActualTransactionActive(true);try{assertThrows(TenantAccessException.class,proof::requireUnchanged);}finally{TransactionSynchronizationManager.clear();}}}
 @Test void truePrivateAdmissionRejectsAnotherThread()throws Exception{try(var scope=original.scope()){TransactionSynchronizationManager.setActualTransactionActive(true);try{var proof=read();var failure=new java.util.concurrent.atomic.AtomicReference<Throwable>();var t=new Thread(()->{try(var other=original.scope()){TransactionSynchronizationManager.setActualTransactionActive(true);try{proof.requireUnchanged();}catch(Throwable e){failure.set(e);}finally{TransactionSynchronizationManager.clear();}}});t.start();t.join();assertInstanceOf(TenantAccessException.class,failure.get());}finally{TransactionSynchronizationManager.clear();}}}
}
